"use strict";

function decode(value) {
  return decodeURIComponent(String(value || "").replace(/\+/g, " "));
}

function encode(value) {
  return encodeURIComponent(String(value));
}

exports.parse = function parse(input) {
  const result = {};
  String(input || "").split("&").filter(Boolean).forEach((pair) => {
    const index = pair.indexOf("=");
    const key = decode(index >= 0 ? pair.slice(0, index) : pair);
    const value = decode(index >= 0 ? pair.slice(index + 1) : "");
    if (Object.prototype.hasOwnProperty.call(result, key)) {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    } else {
      result[key] = value;
    }
  });
  return result;
};

exports.stringify = function stringify(input) {
  const parts = [];
  Object.keys(input || {}).forEach((key) => {
    const value = input[key];
    if (Array.isArray(value)) {
      value.forEach((item) => parts.push(encode(key) + "=" + encode(item)));
    } else {
      parts.push(encode(key) + "=" + encode(value));
    }
  });
  return parts.join("&");
};
